   char **actual = annotate(minefield, rows);
   TEST_ASSERT_EQUAL_STRING_ARRAY(expected, actual, rows);
   free_annotation(actual);
}

static void test_annotate_mine_surrounded_by_spaces(void)
{
   TEST_IGNORE();
