static void test_annotate_large_minefield(void)
{
   TEST_IGNORE();
   const char *minefield[] = {
      // clang-format off
      " *  * ",
      "  *   ",
      "    * ",
      "   * *",
      " *  * ",
      "      "
      // clang-format on
   };
   const char *expected[] = {
      // clang-format off
      "1*22*1",
      "12*322",
      " 123*2",
      "112*4*",
      "1*22*2",
      "111111"
